import Stripe from "stripe";

export const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!, {
  apiVersion: "2024-10-28.acacia",
});

export interface CheckoutInput {
  priceId: string;
  successUrl: string;
  cancelUrl: string;
  customerEmail?: string;
  mode?: "payment" | "subscription";
}

export async function createCheckoutSession(input: CheckoutInput) {
  return stripe.checkout.sessions.create({
    mode: input.mode ?? "payment",
    line_items: [{ price: input.priceId, quantity: 1 }],
    success_url: input.successUrl,
    cancel_url: input.cancelUrl,
    customer_email: input.customerEmail,
  });
}

import { Router, type IRouter, raw } from "express";
import { stripe } from "../lib/stripe";

const router: IRouter = Router();

// IMPORTANT: mount this BEFORE any JSON body parser — Stripe needs the raw body.
router.post("/stripe/webhook", raw({ type: "application/json" }), (req, res) => {
  const sig = req.headers["stripe-signature"] as string | undefined;
  if (!sig) {
    res.status(400).send("Missing signature");
    return;
  }
  let event;
  try {
    event = stripe.webhooks.constructEvent(
      req.body as Buffer,
      sig,
      process.env.STRIPE_WEBHOOK_SECRET!,
    );
  } catch (err) {
    res.status(400).send(`Invalid signature: ${(err as Error).message}`);
    return;
  }
  switch (event.type) {
    case "checkout.session.completed":
      // TODO: fulfil the order — set user as paid, send receipt, etc.
      break;
    case "customer.subscription.deleted":
      // TODO: revoke subscription access.
      break;
  }
  res.json({ received: true });
});

export default router;
